(7134505, 1093277, 117534, '<td valign="top">This IS beautiful!</td>', 'This IS beautiful!', '2013-11-25 00:15:18.000000', NULL, 1),
(7134507, 1093233, 117534, '<td valign="top">Lovely Lit!</td>', 'Lovely Lit!', '2013-11-25 00:16:13.000000', NULL, 1),
