(7134931, 1093173, 18197, '<td valign="top">Not to everyone''s taste and perhaps a bit of a shoehorn, but I like the abstract nature.</td>', 'Not to everyone''s taste and perhaps a bit of a shoehorn, but I like the abstract nature.', '2013-11-25 22:26:27.000000', NULL, 1),
